import numpy as np, torch, model
d=np.load('contrast_c5_out_act_k12.npy'); net=model.load(); neg=model.negatives()
w=torch.tensor(d); b=-24.5235
def dec(z,c,dv,lo,hi):
    x=z.clone()
    for k in range(20):
        t=torch.full((len(x),),1-k/20)
        v,a=net.velocity(x,t,c,("out_act",))
        if lo<=k<hi:
            f=((a["out_act"]@w+b)>0).float(); v=v+f[:,None]*dv
        x=x-v/20
    return x.numpy()
torch.manual_seed(7); M=1024
Z=torch.randn(M,2)
nj=len(neg['uid'])
base={}
for j in range(nj):
    c=torch.full((M,),float(neg['c'][j])); base[j]=np.asarray(model.in_basin(j,dec(Z,c,torch.zeros(2),0,0))).mean()
print('base',{int(neg['uid'][j]):round(base[j],3) for j in range(nj)})
for ang,mag,lo,hi in [(0,20,0,6),(225,20,0,6),(270,20,0,6),(315,20,0,6),(270,8,0,6),(0,8,0,3),(225,8,0,6)]:
    dv=-mag*torch.tensor([np.cos(np.radians(ang)),np.sin(np.radians(ang))],dtype=torch.float32)
    r={}
    for j in range(nj):
        c=torch.full((M,),float(neg['c'][j])); r[j]=np.asarray(model.in_basin(j,dec(Z,c,dv,lo,hi))).mean()-base[j]
    rise=sum(max(0,r[j]) for j in range(nj) if j!=11)
    print(ang,mag,lo,hi,'target',round(r[11],3),'other rises',{int(neg['uid'][j]):round(r[j],3) for j in range(nj) if j!=11 and abs(r[j])>0.004},'sum+',round(rise,3),flush=True)

